def put(n,v):
 if n in ['reading-ledger.json','reception-ledger.json']:
  fields=[]
  for k,item in v.items():
   if k=='records':
    fields.append('  "records": [\n'+',\n'.join('    '+json.dumps(row,ensure_ascii=False,separators=(',',':')) for row in item)+'\n  ]')
   else:
    fields.append('  '+json.dumps(k)+': '+json.dumps(item,ensure_ascii=False,indent=2).replace('\n','\n  '))
  (O/n).write_text('{\n'+',\n'.join(fields)+'\n}\n')
 else:
  (O/n).write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
def identity(root,commit,path):
 data=subprocess.check_output(['git','show',commit+':'+path],cwd=root)
 mode,kind,blob=subprocess.check_output(['git','ls-tree',commit,'--',path],cwd=root).decode().split('\t')[0].split()
 return {'commit':commit,'path':path,'mode':mode,'git_blob':blob,'bytes':len(data),'sha256':hashlib.sha256(data).hexdigest()}
def ref(root,commit,path,ranges,chunks,meaning):
 return {'identity':identity(root,commit,path),'read_ranges':ranges,'tool_output_chunks':chunks,'meaning':meaning,'evidence_level':'SOURCE_STATIC','behavior_execution':'NOT_EXECUTED'}
